class Solution {
public:
    vector<int> topStudents(vector<string>& positive_feedback, vector<string>& negative_feedback, vector<string>& report, vector<int>& student_id, int k) {
        unordered_map<int, long long> scores;
        for (int sid : student_id) scores[sid] = 0;
        for (size_t i = 0; i < report.size(); i++) {
            stringstream ss(report[i]);
            string w;
            while (ss >> w) {
                if (find(positive_feedback.begin(), positive_feedback.end(), w) != positive_feedback.end())
                    scores[student_id[i]] += 3;
                else if (find(negative_feedback.begin(), negative_feedback.end(), w) != negative_feedback.end())
                    scores[student_id[i]] -= 1;
            }
        }
        vector<pair<long long,int>> v(scores.begin(), scores.end());
        sort(v.begin(), v.end(), [](auto& a, auto& b){ return a.first != b.first ? a.first > b.first : a.second < b.second; });
        vector<int> res;
        for (int i = 0; i < k; i++) res.push_back(v[i].second);
        return res;
    }
};

