class Solution {
    public int[] topStudents(String[] positive_feedback, String[] negative_feedback, String[] report, int[] student_id, int k) {
        Map<Integer, Long> scores = new HashMap<>();
        for (int sid : student_id) scores.put(sid, 0L);
        for (int i = 0; i < report.length; i++) {
            for (String w : report[i].split(" ")) {
                boolean found = false;
                for (String p : positive_feedback) {
                    if (p.equals(w)) { scores.merge(student_id[i], 3L, Long::sum); found = true; break; }
                }
                if (!found) for (String ng : negative_feedback) {
                    if (ng.equals(w)) { scores.merge(student_id[i], -1L, Long::sum); break; }
                }
            }
        }
        return scores.entrySet().stream()
            .sorted((a, b) -> !a.getValue().equals(b.getValue()) ? Long.compare(b.getValue(), a.getValue()) : Integer.compare(a.getKey(), b.getKey()))
            .limit(k).mapToInt(Map.Entry::getKey).toArray();
    }
}

