    const scores = new Map(student_id.map(id => [id, 0]));
    for (let i = 0; i < report.length; i++) {
        for (const w of report[i].split(' ')) {
            if (positive_feedback.includes(w)) scores.set(student_id[i], scores.get(student_id[i]) + 3);
            else if (negative_feedback.includes(w)) scores.set(student_id[i], scores.get(student_id[i]) - 1);
        }
